CREATE TABLE `tenants` (`id` UUID PRIMARY KEY, `name` VARCHAR(255) NOT NULL, `slug` VARCHAR(255) NOT NULL UNIQUE, `domain` VARCHAR(255) UNIQUE, `settings` JSON DEFAULT '{"pricing_config":{},"services":["menjador","acollida","extraescolars"],"branding":{"logo":null,"primary_color":"#3B82F6","secondary_color":"#EF4444"},"contact":{"email":null,"phone":null,"address":null}}', `status` TEXT DEFAULT 'active', `subscription_plan` TEXT DEFAULT 'basic', `max_students` INTEGER DEFAULT 100, `created_at` DATETIME, `updated_at` DATETIME);
