CREATE TABLE `students` (`id` UUID PRIMARY KEY, `tenant_id` UUID NOT NULL REFERENCES `tenants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `first_name` VARCHAR(255) NOT NULL, `last_name` VARCHAR(255) NOT NULL, `birth_date` DATE NOT NULL, `class_group` VARCHAR(255) NOT NULL, `photo_url` VARCHAR(255), `status` TEXT DEFAULT 'active', `student_code` VARCHAR(255) UNIQUE, `medical_info` JSON DEFAULT '{"allergies":[],"medications":[],"emergency_contact":null,"special_needs":null,"dietary_restrictions":[]}', `academic_year` VARCHAR(255) NOT NULL, `created_at` DATETIME, `updated_at` DATETIME);
