CREATE TABLE `student_family` (`id` UUID PRIMARY KEY, `student_id` UUID NOT NULL REFERENCES `students` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `user_id` UUID NOT NULL REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `relationship` TEXT NOT NULL DEFAULT 'pare', `is_primary_contact` TINYINT(1) DEFAULT 0, `can_pickup` TINYINT(1) DEFAULT 1, `emergency_contact` TINYINT(1) DEFAULT 0, `notes` TEXT, `created_at` DATETIME, `updated_at` DATETIME, UNIQUE (`student_id`, `user_id`));
