CREATE TABLE `persones_autoritzades` (`id` UUID PRIMARY KEY, `student_id` UUID NOT NULL REFERENCES `students` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `tenant_id` UUID NOT NULL REFERENCES `tenants` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE, `nom` VARCHAR(100) NOT NULL, `cognoms` VARCHAR(150) NOT NULL, `dni_nie` VARCHAR(15) NOT NULL, `telefon_principal` VARCHAR(20) NOT NULL, `telefon_secundari` VARCHAR(20), `email` VARCHAR(150), `relacio_familiar` TEXT NOT NULL, `prioritat_contacte` INTEGER DEFAULT 1, `autoritzat_recollir` TINYINT(1) DEFAULT 1, `autoritzat_decisio_medica` TINYINT(1) DEFAULT 0, `foto_autoritzacio_url` TEXT, `observacions` TEXT, `actiu` TINYINT(1) DEFAULT 1, `created_at` DATETIME, `updated_at` DATETIME, UNIQUE (`dni_nie`));
CREATE TABLE `student_documents` (`id` UUID PRIMARY KEY, `student_id` UUID NOT NULL REFERENCES `students` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `tenant_id` UUID NOT NULL REFERENCES `tenants` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE, `uploaded_by` UUID NOT NULL REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE, `tipus_document` TEXT NOT NULL, `nom_fitxer` VARCHAR(255) NOT NULL, `nom_original` VARCHAR(255) NOT NULL, `ruta_fitxer` TEXT NOT NULL, `mida_bytes` BIGINT NOT NULL, `tipus_mime` VARCHAR(100) NOT NULL, `hash_fitxer` VARCHAR(64) NOT NULL, `descripcio` TEXT, `data_caducitat` DATE, `estat_verificacio` TEXT DEFAULT 'pendent', `verificat_per` UUID REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `data_verificacio` DATETIME, `notes_verificacio` TEXT, `visible_familia` TINYINT(1) DEFAULT 1, `actiu` TINYINT(1) DEFAULT 1, `created_at` DATETIME, `updated_at` DATETIME);
CREATE TABLE `student_medical` (`id` UUID PRIMARY KEY, `student_id` UUID NOT NULL UNIQUE REFERENCES `students` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `tenant_id` UUID NOT NULL REFERENCES `tenants` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE, `grup_sanguini` TEXT DEFAULT 'desconegut', `numero_targeta_sanitaria` VARCHAR(50), `centre_sanitari_assignat` VARCHAR(200), `metge_pediatra` VARCHAR(200), `telefon_urgencies_mediques` VARCHAR(20), `te_allergies` TINYINT(1) DEFAULT 0, `allergies_alimentaries` TEXT, `allergies_medicaments` TEXT, `allergies_ambientals` TEXT, `intolerancies_alimentaries` TEXT, `pren_medicacio_habitual` TINYINT(1) DEFAULT 0, `medicacio_detalls` TEXT, `condicions_mediques` TEXT, `necessitats_especials` TEXT, `autoritzacio_medicacio_escola` TINYINT(1) DEFAULT 0, `autoritzacio_tractament_urgencia` TINYINT(1) DEFAULT 0, `autoritzacio_activitat_fisica` TEXT DEFAULT 'sense_limitacions', `dieta_especial` TINYINT(1) DEFAULT 0, `tipus_dieta` TEXT DEFAULT 'normal', `detalls_dieta` TEXT, `contacte_emergencia_1_nom` VARCHAR(200), `contacte_emergencia_1_telefon` VARCHAR(20), `contacte_emergencia_1_relacio` VARCHAR(100), `contacte_emergencia_2_nom` VARCHAR(200), `contacte_emergencia_2_telefon` VARCHAR(20), `contacte_emergencia_2_relacio` VARCHAR(100), `observacions_generals` TEXT, `darrera_revisio_medica` DATE, `revisio_per` UUID REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `created_at` DATETIME, `updated_at` DATETIME);
